import os
from google.cloud import documentai_v1 as documentai

def get_document_ai_client():
    return documentai.DocumentProcessorServiceClient()

def get_document_ai_processor_path(project_id, location, processor_id):
    return documentai.DocumentProcessorServiceClient.processor_path(
        project_id, location, processor_id
    )

from document_models import NormalizedExpense
from typing import Dict, Any

def validate_document_fields(expense: NormalizedExpense, required_fields: list[str]) -> Dict[str, Any]:
    validation_results = {"is_valid": True, "missing_fields": [], "field_validations": {}}

    for field in required_fields:
        if not getattr(expense, field, None):
            validation_results["is_valid"] = False
            validation_results["missing_fields"].append(field)
            validation_results["field_validations"][field] = {"present": False, "reason": "missing"}
        else:
            validation_results["field_validations"][field] = {"present": True}

    # Placeholder for confidence score validation, if applicable in the future
    # if expense.raw_extraction_data and "confidence" in expense.raw_extraction_data:
    #     if expense.raw_extraction_data["confidence"] < 0.7: # Example threshold
    #         validation_results["is_valid"] = False
    #         validation_results["field_validations"]["document_confidence"] = {"valid": False, "reason": "low confidence"}

    expense.validation_results = validation_results
    return validation_results

import os
from google.cloud import aiplatform
from document_models import NormalizedExpense

def summarize_invoice_fields(expense: NormalizedExpense, config=None) -> str:
    config = config or {}
    project_id = config.get("project_id", os.environ.get("GOOGLE_CLOUD_PROJECT"))
    location = config.get("location", "us-central1") # e.g., "us-central1"
    model_name = config.get("model_name", "gemini-pro")

    if not all([project_id, location, model_name]):
        raise ValueError("Google Cloud project_id, location, and Vertex AI model_name must be provided.")

    aiplatform.init(project=project_id, location=location)
    model = aiplatform.GenerativeModel(model_name)

    prompt = f"""Summarize the following expense document. Highlight the vendor, total amount, and key line items.

Vendor: {expense.vendor_name}
Date: {expense.transaction_date}
Total: {expense.total_amount}
Document Type: {expense.document_type}
Line Items: {', '.join([f'{item.description} ({item.amount})' for item in expense.line_items]) if expense.line_items else 'N/A'}
"""

    response = model.generate_content(prompt)
    summary = response.text
    expense.summary = summary
    return summary
